(function(){"use strict";app.factory("menuService",function(n){const i=n.get("mainService"),r="Config/Menu/",u="Config/SubMenu/",t={};return t.get=function(n){return i.getData("get",r+"?json="+JSON.stringify(n)).then(n=>{if(n.code==="0")throw n;if(n.code==="1"){let t=JSON.parse(n.payload)||[];return t[0]}})},t.save=function(n){return i.getData("post",`${r}?json=${JSON.stringify(n)}`,null,!0)},t.update=function(n,t){return i.getData("put",`${r}${n}?json=${JSON.stringify(t)}`,null,!0)},t.delete=function(n){return i.getData("delete",r+n,null,!0)},t.findByIdMenu=function(n){return i.getData("get",u+"FindByIdMenu/"+n).then(n=>{if(n.code==="0")throw n;if(n.code==="1")return JSON.parse(n.payload)||[]})},t.saveSubMenu=function(n){return i.getData("post",`${u}?json=${JSON.stringify(n)}`,null,!0)},t.updateSubMenu=function(n,t){return i.getData("put",`${u}${n}?json=${JSON.stringify(t)}`,null,!0)},t.deleteSubMenu=function(n){return i.getData("delete",u+n,null,!0)},t})})(window.angular);